function get_header_footer($company) {
    $header = '<span id="printableSection"><body style="font-family: Arial, sans-serif; background-color: #f0f0f0; margin: 0; padding: 0;">
        <div style="max-width: 600px; margin: 0 auto; background-color: white; padding: 20px; border-radius: 10px; box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);">
            <div display: flex>';
            if($company[0]->status == 2)
                $header .= '<b><span style="font-size: 20px !important; float: left; width: 60%; margin: 20px 0; text-align: right; color: #1A3231; padding: 8px 0; font-weight: 8px; background-color: "></span></b>';
            else if($company[0]->status == 4)
                $header .= '<b><span style="font-size: 20px !important; float: left; width: 60%; margin: 20px 0; text-align: right; color: #1A3231; padding: 8px 0; font-weight: 8px; background-color: "></span>العقـــــد</b>';
            else
                $header .= '<b><span style="font-size: 20px !important; float: left; width: 60%; margin: 20px 0; text-align: right; color: #1A3231; padding: 8px 0; font-weight: 8px; background-color: ">عرض الســـــعر</span></b>';
            if($company[0]->status != 4)
                $header .= '<span style="text-align: right;width: 40%"><p><img src="data:image/png;base64," style="height:80px; width:70px" /></p></span>
            ';
            if($company[0]->status != 4) {
                $header .= '</div>
                <p style="color: #1A3231;direction: rtl; font-size: 12px;"><b>عرض السعر: </b>'.$company[0]->ref_no.' </p>
                <p style="color: #1A3231;direction: rtl; font-size: 12px;"><b> التاريخ:</b>'.date("Y/m/d").'
                <hr style="background-color: #EBEBEA;height: 3px;border: 1px;">';
            }
            $header .= '<p style="color: #1A3231;direction: rtl;font-size: 13px;"><b>
            أهلاً
            عملينا العزيز
            !
            </b>
            </p>';
    $footer = '<br><div style="text-align: center; display: flex; align-items: center;">
                <hr style="flex-grow: 1; border: none; border: 1px solid #000; width: 80%">
                <div style="padding: 0 10px;"><p><img style="width: 60px; height: 30px" src="data:image/png;base64," /></p>
                </div>
                <hr style="flex-grow: 1; border: none; border: 1px solid #000;">
            </div>';
    return array($header, $footer);
}



