    // Show blade data function
    public function verification(Request $request)
    {
        $user_id = Auth::user()->id;
        $id = $request->id;
        $row = DB::select("SELECT type, cont_end_date FROM contracts_quotations WHERE id = '$id'");
        if($row[0]->type == 'contract' AND $row[0]->cont_end_date == '') {
            $template = '<span id="items_table"></span>';
        } else {
            $template = get_email_template($id);
        }
        return $template;
    }
    
    // HR process
    public function reject_file(Request $request)
    {
        $id = $request->id;
        $column = $request->column;
        DB::update("UPDATE contracts_quotations set $column = '1' WHERE id = '$id'");
        return response()->json(['message' => 'File rejected successfully'], 200);
    }
    public function sendContract(Request $request)
    {
        $id = $request->id;
        $quot_status = $request->quot_status;
        $row = DB::select("SELECT * FROM contracts_quotations WHERE id = '$id'");
        $company = $row[0]->companyName;
        $email = $row[0]->companyEmail;
        $cont_start_date = $request->cont_start_date;
        if($quot_status == 1) {
            $ceo_ip = $request->ip();
            $apiUrl = "http://ip-api.com/json/{$ceo_ip}";
            $response = file_get_contents($apiUrl);
            $data = json_decode($response, true);
            if ($data["status"] === "success") {
                $ceo_address = $data['city'] . ', ' . $data['country'];
                DB::update("UPDATE contracts_quotations set ceo_ip = '$ceo_ip', ceo_address = '$ceo_address', ceo_signature_date = NOW(), cont_start_date = '$cont_start_date', status = '2' WHERE id = '$id'");
                $row = DB::select("SELECT * FROM contracts_quotations WHERE id = '$id'");
                $head_foot = get_header_footer($row);
                $msg = $head_foot[0];
                // <br>لو سمحت<a href="'.url('').'/ContractAccept/'.base64_encode($row[0]->id).'">انقر هنا</a> لقراءة العقد.
                $msg .= '
                <p style="color: #1A3231;direction: rtl; font-size: 13px;">نحن على ثقة من أن هذا البريد الإلكتروني يجدك جيدًا
                    <br>لو سمحت<a href="'.url('').'/verification/'.base64_encode($row[0]->id).'">انقر هنا</a> لقراءة العقد.
                    <br>يمكنك أيضًا مسح رمز الاستجابة السريعة التالي لقراءة العقد
                </p>
                <p style="direction: rtl">
                    <img style="width: 150px; height: 150px" src="https://chart.googleapis.com/chart?chs=200x200&cht=qr&chl='.url('').'/verification/'.base64_encode($row[0]->id).'%2F&choe=UTF-8" title="Verification" />
                </p>
                <br><br>';
                // If you wanna reject this contract please <a href="'.url('').'/ContractReject/'.base64_encode($row[0]->id).'">click here</a>
                // $msg .= 'Please <a href="'.url('').'/ContractAccept/'.base64_encode($row[0]->id).'">click here</a> to read the contract.<br><br>';
                $msg .= $head_foot[1];
                $msg .= '</div>
                </span>';
                
                $recipients = [
                    $email,
                    // 'm.shehroze@btclogistic.com',
                ];
                $ccRecipients = [
                    // 'cpm@btclogistic.com',
                ];
                $subject = "Contract by BTC";
                $email_status = HelperFunctionsController::send_email($recipients, $ccRecipients, $msg, $subject);
                if($email_status == false) {
                    return response()->json(['message' => 'Failed to send email.'], 500);
                } else {
                    return redirect('ContractsQuotation')->with('success', "Contract sent successfully");
                }
            } else {
                return redirect('ContractsQuotation')->with('error', "Unable to find your location");
            }
        } else if($quot_status == 0) {
            $reject_reason = HelperFunctionsController::clean_string($request->reject_reason);
            $cont_date_clause = "cont_start_date = '$cont_start_date',";
            if($cont_start_date === null)
                $cont_date_clause = "";    
            DB::update("UPDATE contracts_quotations set $cont_date_clause reject_reason = '$reject_reason', status = '3' WHERE id = '$id'");
            if ($row[0]->type == 'contract') {
                $msg = "Hi <b>$company</b>, <br><br>We trust this email find you well.<br><br>You provided some invalid data.<br>";
                if($reject_reason != '') {
                    $msg .= '<p>Please review the following comments by BTC HR.</p>';
                    $msg .= $reject_reason;
                    $msg .= '<br><br>';
                }
                $msg .= 'Please <a href="'.url('').'/QuotationAccept/'.base64_encode($row[0]->id).'">Click here</a> to provide correct data again.<br><br><br>';
                $msg .= 'Best Regards<br>';
                $msg .= 'Bandar Trading Company';
                
                $subject = "Required information for BTC Contract";
            } else {
                $head_foot = get_header_footer($row);
                $msg = $head_foot[0];
                $msg .= '
                <p style="color: #1A3231;direction: rtl; font-size: 13px;">نحن على ثقة من أن هذا البريد الإلكتروني يجدك جيدًا
                </p>';
                if($reject_reason != '') {
                    $msg .= '<p style="color: #1A3231;direction: rtl; font-size: 13px;">يرجى النظر أدناه إلى التعليقات المقدمة من BTC HR.</p><br><br>';
                    $msg .= $reject_reason;
                    $msg .= '<br><br>';
                }
                $msg .= '<p style="color: #1A3231;direction: rtl; font-size: 13px;">لقد قدمت بعض المعلومات الخاطئة من قبل، من فضلك <a href="'.url('').'/QuotationAccept/'.base64_encode($row[0]->id).'">انقر هنا</a> لتصحيح المعلومات مرة أخرى.<br><br>';
                $msg .= $head_foot[1];
                $msg .= '</div>
                </span>';
                $subject = "Quotation by BTC";
            }
            
            $recipients = [
                $email,
                // 'm.shehroze@btclogistic.com',
            ];
            $ccRecipients = [
                // 'cpm@btclogistic.com',
            ];
            $email_status = HelperFunctionsController::send_email($recipients, $ccRecipients, $msg, $subject);
            if($email_status == false) {
                return response()->json(['message' => 'Failed to send email.'], 500);
            } else {
                return redirect('ContractsQuotation')->with('success', "Quotation sent again successfully");
            }
        }
    }
    //  end HR
    public function index(Request $request)
    {
        $user_id = Auth::user()->id;
        $contracts = DB::select('SELECT contracts_quotations.*, users.`name` as user_name from contracts_quotations join users on contracts_quotations.created_by = users.id order by created_at desc');
        $approved_users = DB::select('SELECT * from contracts_quotations_approved_by');
        $approval_users = DB::select("SELECT contracts_quotations_approval_users.emp_id, users.`name` FROM contracts_quotations_approval_users INNER JOIN users ON contracts_quotations_approval_users.emp_id=users.id ORDER BY CASE WHEN users.id = '$user_id' THEN 0 ELSE 1 END, users.id");
        
        return view('ContractsQuotation.index')->with('contracts', $contracts)->with('approved_users', $approved_users)->with('approval_users', $approval_users);
    }
    
    public function create(Request $request)
    {
        $type = $request->type;
        $companies = DB::select('SELECT * from lkp_contracts_quotations_companies');

        $units = DB::select('SELECT * from lkp_contracts_quotations_items_unit');
        $contract_types = DB::select('SELECT * from lkp_contract_type');
        $items = DB::select('SELECT * from lkp_contracts_quotations_items');
        $options = "<option value=''>Select Item</option>";
        foreach($items as $item)
            $options .= "<option value='$item->id'>$item->name</option>";
        $options .= "<option value='other'>Other</option>";
        
        return view('ContractsQuotation.create')->with('type', $type)->with('options', $options)->with('contract_types', $contract_types)->with('companies', $companies);
    }
