        $descriptions = $request->description;
        $descriptions_ar = $request->description_ar;
        $vehicle_info_checks = $request->vehicle_info_check;
        $vehicle_infos = $request->vehicle_info;
        $vehicle_infos_ar = $request->vehicle_info_ar;
        $quantitys = $request->quantity;
        $prices = $request->price;
        $types = $request->types;
