            DB::insert("INSERT into lkp_contracts_quotations_companies (name_en, name_ar, companyEmail) VALUES ('$companyName', '$companyName_ar', '$companyEmail')");
        }
        $user_id = Auth::user()->id;
        DB::insert("INSERT into contracts_quotations (contractType, type, companyName, companyName_ar, companyEmail, body, created_by, created_at) VALUES ('$contractType', '$type', '$companyName', '$companyName_ar', '$companyEmail', '$body', '$user_id', NOW())");
        $id = DB::getPdo()->lastInsertId();
        for ($i = 0; $i < sizeof($names); $i++) {
