                        $vehicle_info = '';
                        $vehicle_info_ar = '';
                    }
                    else {
                        $vehicle_info_check = 0;
                        $vehicle_info = $vehicle_infos[$i];
                        $vehicle_info_ar = $vehicle_infos_ar[$i];
                    }
                    $quantity = $quantitys[$i];
                    $quot_check = DB::select("SELECT id from lkp_contracts_quotations_items where name = '$name'");
                    if(count($quot_check) > 0){} else {
                        DB::insert("INSERT into lkp_contracts_quotations_items (type, name, name_ar, description, description_ar, vehicle_info_check, vehicle_info, vehicle_info_ar, price, created_by, created_at) VALUES ('1', '$name', '$name_ar', '$description', '$description_ar', '$vehicle_info_check', '$vehicle_info', '$vehicle_info_ar', '$price', '$user_id', NOW())");
                    }
                    DB::insert("INSERT into contracts_quotations_items (type, quot_id, name, name_ar, description, description_ar, vehicle_info_check, vehicle_info, vehicle_info_ar, quantity, price, created_by, created_at) VALUES ('1', '$id', '$name', '$name_ar', '$description', '$description_ar', '$vehicle_info_check', '$vehicle_info', '$vehicle_info_ar', '$quantity', '$price', '$user_id', NOW())");
                }
